  if (xs.length === 0) return 0;
  return xs.reduce((a, b) => a + b, 0) / xs.length;
}

export function median(xs) {
  if (xs.length === 0) return 0;
  const s = [...xs].sort((a, b) => a - b);
  const m = s.length >> 1;
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
}
EOF
cat > test/stats.test.js <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { mean, median } from "../src/stats.js";
import { summary } from "../src/report.js";
test("mean", () => assert.equal(mean([2, 4]), 3));
test("median odd", () => assert.equal(median([5, 1, 3]), 3));
test("median even", () => assert.equal(median([4, 1, 3, 2]), 2.5));
test("median empty", () => assert.equal(median([]), 0));
test("median does not mutate", () => {
  const xs = [3, 1, 2];
  median(xs);
  assert.deepEqual(xs, [3, 1, 2]);
});
test("summary", () => assert.equal(summary([2, 4]), "mean=3"));
EOF
sed -i '' 's/average/mean/g' src/report.js
